#!/usr/bin/env python3
"""编译原 init 观察器实际生成的 iOS runner/execution，记录输入与输出摘要。"""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[2]
WORK = ROOT / 'work/native-linux-nce'


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source-report', type=Path, required=True)
    parser.add_argument('--runtime-report', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    source_path, runtime_path, output = (path.resolve() for path in
                                         (args.source_report, args.runtime_report, args.output))
    if not all(path.is_relative_to(WORK) for path in (source_path, runtime_path, output)):
        raise ValueError('输入与输出必须位于本树 work/native-linux-nce')
    source = json.loads(source_path.read_text())
    runtime = json.loads(runtime_path.read_text())
    if runtime['target'] != 'ios' or not source['runs']:
        raise ValueError('需要原 init 观察报告和 iOS runtime')
    if source['source_configuration'] != runtime['configuration']:
        raise ValueError('原 init 与 iOS runtime 配置不同')
    inputs = dict(source['sha256'])
    for name, expected in runtime['sha256'].items():
        if name in inputs and inputs[name] != expected:
            raise ValueError('两份报告输入不同：' + name)
        inputs[name] = expected
    for name, expected in inputs.items():
        if digest(ROOT / name) != expected:
            raise ValueError('编译输入已变化：' + name)
    if digest(Path(runtime['library'])) != runtime['library_sha256']:
        raise ValueError('iOS runtime 静态库摘要不同')
    output.mkdir(parents=True, exist_ok=False)
    commands, objects = [], {}
    for name in ('linux-runner.c', 'linux-execution.c'):
        command = next(list(command) for command in runtime['commands']
                       if '-c' in command and Path(command[command.index('-c') + 1]).name == name)
        command[command.index('-c') + 1] = str(source_path.parent / name)
        obj = output / (Path(name).stem + '.o')
        command[command.index('-o') + 1] = str(obj)
        command += ['-iquote', str(ROOT / 'experiments/native-linux/translation')]
        subprocess.run(command, check=True, timeout=120)
        commands.append(command)
        objects[str(obj.relative_to(ROOT))] = digest(obj)
    for path in (Path(__file__), source_path, runtime_path, Path(runtime['library'])):
        inputs[str(path.relative_to(ROOT))] = digest(path)
    if any(digest(ROOT / name) != expected for name, expected in inputs.items()):
        raise ValueError('编译期间输入变化')
    result = {'scope': 'Generated original init runner/execution iOS cross compilation; device execution pending',
              'target': 'ios', 'commands': commands, 'source_report': str(source_path),
              'source_observation_validated': all(run['observation_validated'] for run in source['runs']),
              'source_report_sha256': digest(source_path), 'runtime_report': str(runtime_path),
              'runtime_report_sha256': digest(runtime_path), 'sha256': inputs, 'objects_sha256': objects}
    report = output / 'init-copy-build.json'
    report.write_text(json.dumps(result, indent=2) + '\n')
    print(report)


if __name__ == '__main__':
    main()
